{
  "name": "find_shared_free_slot",
  "request_shape": "Find a free one-hour slot next week that works for both Dana Reyes and Sam Okafor, and propose it to them.",
  "inputs": [],
  "steps": [
    {
      "id": "get_dana_calendar",
      "kind": "list",
      "source": "calendar",
      "filter": "owner=Dana Reyes AND date >= next_monday AND date <= next_sunday"
    },
    {
      "id": "get_sam_calendar",
      "kind": "list",
      "source": "calendar",
      "filter": "owner=Sam Okafor AND date >= next_monday AND date <= next_sunday"
    },
    {
      "id": "generate_candidate_slots",
      "kind": "list",
      "source": "calendar",
      "filter": "owner=system AND date >= next_monday AND date <= next_sunday AND duration=1h AND type=free"
    },
    {
      "id": "batch_dana",
      "kind": "batch",
      "size": 1,
      "inputs": ["get_dana_calendar"]
    },
    {
      "id": "batch_sam",
      "kind": "batch",
      "size": 1,
      "inputs": ["get_sam_calendar"]
    },
    {
      "id": "batch_candidates",
      "kind": "batch",
      "size": 1,
      "inputs": ["generate_candidate_slots"]
    },
    {
      "id": "loop_dana_conflicts",
      "kind": "loop_over_items",
      "over": "batch_dana",
      "steps": [
        {
          "id": "check_dana_slot_free",
          "kind": "classify",
          "enum": ["busy", "free"],
          "question": "Is this candidate slot busy for Dana Reyes?",
          "inputs": ["batch_candidates"]
        }
      ]
    },
    {
      "id": "loop_sam_conflicts",
      "kind": "loop_over_items",
      "over": "batch_sam",
      "steps": [
        {
          "id": "check_sam_slot_free",
          "kind": "classify",
          "enum": ["busy", "free"],
          "question": "Is this candidate slot busy for Sam Okafor?",
          "inputs": ["batch_candidates"]
        }
      ]
    },
    {
      "id": "filter_shared_free",
      "kind": "check_coverage",
      "rule": "output must contain only slots where Dana is free AND Sam is free"
    },
    {
      "id": "select_first_slot",
      "kind": "list",
      "source": "filter_shared_free",
      "filter": "limit=1"
    },
    {
      "id": "draft_proposal",
      "kind": "write",
      "instruction": "Draft a polite email proposing the selected time slot to Dana Reyes and Sam Okafor.",
      "max_words": 50,
      "inputs": ["select_first_slot"]
    },
    {
      "id": "check_proposal_validity",
      "kind": "check_coverage",
      "rule": "output must contain the exact time slot from select_first_slot"
    }
  ],
  "output": "draft_proposal"
}
